cd /opt/gsb-fleet/workspaces/inst-35/A/task054
echo '### 1) each spelling ALONE is legal (escape-spelled, single quotes keep \\u) ###'
printf '%s\n' '{"timestamp":"2026-10-04T08:30:00Z","action":"café"}' | ./bin/relayproof normalize
printf '%s\n' '{"timestamp":"2026-10-04T08:32:00Z","event_type":"café"}' | ./bin/relayproof normalize
echo
echo '### 2) both together (3-line batch via quoted heredoc) ###'
./bin/relayproof normalize <<'EOF'
{"timestamp":"2026-10-04T08:30:00Z","action":"café"}
{"timestamp":"2026-10-04T08:31:00Z","action":"café","event_type":"café"}
{"timestamp":"2026-10-04T08:32:00Z","event_type":"café"}
EOF
echo "exit=$?"
echo
echo '### 3) codepoint dumper over the same batch (proves the two differ) ###'
./bin/relayproof normalize <<'EOF' | python3 -c 'import sys,json,re
{"timestamp":"2026-10-04T08:30:00Z","action":"café"}
{"timestamp":"2026-10-04T08:31:00Z","action":"café","event_type":"café"}
{"timestamp":"2026-10-04T08:32:00Z","event_type":"café"}
EOF
for r in map(json.loads,sys.stdin):
    if r["ok"]: vs=[("action",r["event"]["action"])]
    else:
        m=re.search(r"\"(.*?)\" and \"(.*?)\"$",r["error"]); vs=[("action",m.group(1)),("event_type",m.group(2))]
    for k,v in vs:
        print("line",r["line"],k," ".join("U+%04X"%ord(c) for c in v))'

